// Binary Tree Node class\nclass TreeNode {\n  constructor(value) {\n    this.value = value;
    this.left = null;
    this.right = null;
  }
}

// Binary Search Tree class\nclass BST {\n  constructor() {\n    this.root = null;
  }
  \n  // Insert value\n  insert(value) {\n    const newNode = new TreeNode(value);
    \n    const insertNode = (node, newNode) => {
      if (value < node.value) {
        if (node.left === null) {
          node.left = newNode;
        } else {
          insertNode(node.left, newNode);
        }
      } else {
        if (node.right === null) {
          node.right = newNode;
        } else {
          insertNode(node.right, newNode);
        }
      }
    };
    \n    if (this.root === null) {
      this.root = newNode;
    } else {
      insertNode(this.root, newNode);
    }
  }
  \n  // Inorder Traversal\n  inorderTraversal() {
    const result = [];
    const inorder = (node) => {
      if (node !== null) {
        inorder(node.left);
        result.push(node.value);
        inorder(node.right);
      }
    };
    inorder(this.root);
    return result;
  }
  \n  // Preorder Traversal\n  preorderTraversal() {
    const result = [];
    const preorder = (node) => {
      if (node !== null) {
        result.push(node.value);
        preorder(node.left);
        preorder(node.right);
      }
    };
    preorder(this.root);
    return result;
  }
  \n  // Postorder Traversal\n  postorderTraversal() {
    const result = [];
    const postorder = (node) => {
      if (node !== null) {
        postorder(node.left);
        postorder(node.right);
        result.push(node.value);
      }
    };
    postorder(this.root);
    return result;
  }
}

// Example usage\nconst bst = new BST();\nbst.insert(10);\nbst.insert(5);\nbst.insert(15);\nbst.insert(3);\nbst.insert(7);\nconsole.log('Inorder:', bst.inorderTraversal()); \n// [3, 5, 7, 10, 15]\nconsole.log('Preorder:', bst.preorderTraversal()); \n// [10, 5, 3, 7, 15]\nconsole.log('Postorder:', bst.postorderTraversal()); \n// [3, 7, 5, 15, 10]
